const ScreenLoading = () => {
  const [textIdx, setTextIdx] = useState(0);
  const texts = [
    "Extracting prerequisites...",
    "Mapping skill dependencies...",
    "Estimating timelines...",
    "Structuring spatial roadmap..."
  ];

  useEffect(() => {
    const interval = setInterval(() => {
      setTextIdx(i => (i + 1) % texts.length);
    }, 2000);
    return () => clearInterval(interval);
  }, []);

  return (
    <motion.div 
      className="screen-container centered"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
    >
      <div className="loading-visual">
        <motion.div 
          className="pulsing-node"
          animate={{ scale: [1, 1.2, 1], opacity: [0.5, 1, 0.5] }}
          transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
        />
        <motion.div 
          className="pulsing-ring"
          animate={{ scale: [1, 2], opacity: [0.8, 0] }}
          transition={{ duration: 2, repeat: Infinity, ease: "easeOut" }}
        />
      </div>
      <AnimatePresence mode="wait">
        <motion.p 
          key={textIdx}
          className="loading-text"
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -10 }}
        >
          {texts[textIdx]}
        </motion.p>
      </AnimatePresence>
    </motion.div>
  );
};

const MilestoneNode = ({ milestone, onDrilldown, onCompressRequest, isAtRisk }) => {
  const x = useMotionValue(0);
  const [isDragging, setIsDragging] = useState(false);

  return (
    <motion.div 
      className={`milestone-node ${isAtRisk ? 'at-risk' : ''}`}
      data-node-id={milestone.id}
      drag="x"
      dragConstraints={{ left: -100, right: 0 }}
      dragElastic={0.1}
      style={{ x }}
      onDragStart={() => setIsDragging(true)}
      onDragEnd={(e, info) => {
        setIsDragging(false);
        if (info.offset.x < -50) {
          // Trigger compression
          const newDuration = Math.max(1, Math.floor(milestone.duration_weeks / 2));
          onCompressRequest(milestone, newDuration, () => {
            // Revert callback
            animate(x, 0, { type: "spring", stiffness: 300, damping: 20 });
          });
        } else {
          animate(x, 0, { type: "spring", stiffness: 300, damping: 20 });
        }
      }}
      onClick={() => {
        if (!isDragging && x.get() === 0) onDrilldown(milestone);
      }}
      whileHover={{ scale: 1.02, borderColor: 'var(--nu-red)' }}
      whileTap={{ scale: 0.98 }}
      layoutId={`node-${milestone.id}`}
    >
      <div className="node-header">
        <span className="node-duration">{milestone.duration_weeks}w</span>
        {isAtRisk && <lucide.AlertTriangle size={14} color="var(--warning)" />}
      </div>
      <h3 className="node-title">{milestone.title}</h3>
      <p className="node-desc">{milestone.description}</p>

      {/* Drag indicator */}
      <div className="drag-handle">
        <lucide.GripVertical size={14} />
      </div>
    </motion.div>
  );
};

const ScreenRoadmap = ({ roadmap, onDrilldown, onCompressRequest, atRiskNodes }) => {
  const containerRef = useRef(null);
  const [lines, setLines] = useState([]);

  const updateLines = useCallback(() => {
    if (!containerRef.current || !roadmap) return;
    const containerRect = containerRef.current.getBoundingClientRect();
    const newLines = [];

    roadmap.milestones.forEach(m => {
      if (!m.dependencies || m.dependencies.length === 0) return;
      const targetEl = document.querySelector(`[data-node-id="${m.id}"]`);
      if (!targetEl) return;
      const targetRect = targetEl.getBoundingClientRect();

      m.dependencies.forEach(depId => {
        const sourceEl = document.querySelector(`[data-node-id="${depId}"]`);
        if (!sourceEl) return;
        const sourceRect = sourceEl.getBoundingClientRect();

        // Calculate centers relative to container
        const startX = sourceRect.right - containerRect.left;
        const startY = sourceRect.top + (sourceRect.height / 2) - containerRect.top;
        const endX = targetRect.left - containerRect.left;
        const endY = targetRect.top + (targetRect.height / 2) - containerRect.top;

        newLines.push({ id: `${depId}-${m.id}`, startX, startY, endX, endY });
      });
    });
    setLines(newLines);
  }, [roadmap]);

  useLayoutEffect(() => {
    // Small delay to ensure DOM is painted
    const timer = setTimeout(updateLines, 100);
    window.addEventListener('resize', updateLines);
    return () => {
      clearTimeout(timer);
      window.removeEventListener('resize', updateLines);
    };
  }, [updateLines]);

  if (!roadmap) return null;

  const sortedPhases = [...roadmap.phases].sort((a, b) => a.order - b.order);

  return (
    <motion.div 
      className="roadmap-canvas"
      ref={containerRef}
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
    >
      <svg className="dependency-lines">
        {lines.map(line => {
          const cp1X = line.startX + (line.endX - line.startX) / 2;
          const cp1Y = line.startY;
          const cp2X = line.startX + (line.endX - line.startX) / 2;
          const cp2Y = line.endY;
          const pathD = `M ${line.startX} ${line.startY} C ${cp1X} ${cp1Y}, ${cp2X} ${cp2Y}, ${line.endX} ${line.endY}`;
          return (
            <path 
              key={line.id} 
              d={pathD} 
              className="dep-path"
              initial={{ pathLength: 0, opacity: 0 }}
              animate={{ pathLength: 1, opacity: 1 }}
              transition={{ duration: 0.8, ease: "easeInOut" }}
            />
          );
        })}
      </svg>

      <div className="phases-container">
        {sortedPhases.map((phase, idx) => (
          <motion.div 
            key={phase.id} 
            className="phase-column"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: idx * 0.2 }}
          >
            <div className="phase-header">
              <h2 className="phase-title">{phase.title}</h2>
              <span className="phase-duration">{phase.duration_weeks} weeks</span>
            </div>
            <div className="phase-milestones">
              {roadmap.milestones
                .filter(m => m.phase_id === phase.id)
                .map(m => (
                  <MilestoneNode 
                    key={m.id} 
                    milestone={m} 
                    onDrilldown={onDrilldown}
                    onCompressRequest={onCompressRequest}
                    isAtRisk={atRiskNodes.includes(m.id)}
                  />
                ))}
            </div>
          </motion.div>
        ))}
      </div>
    </motion.div>
  );
};

const DrilldownPanel = ({ milestone, baseline, onClose }) => {
  const [content, setContent] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let isMounted = true;
    const fetchPlan = async () => {
      try {
        const md = await api.drillDown(milestone, baseline);
        if (isMounted) {
          setContent(md);
          setLoading(false);
        }
      } catch (err) {
        if (isMounted) {
          setError("Failed to generate micro-plan. Please try again.");
          setLoading(false);
        }
      }
    };
    fetchPlan();
    return () => { isMounted = false; };
  }, [milestone, baseline]);

  // Simple markdown renderer for the specific expected format
  const renderMarkdown = (md) => {
    if (!md) return null;
    const lines = md.split('\n');
    return lines.map((line, i) => {
      if (line.startsWith('###')) return <h4 key={i} className="md-h4">{line.replace('###', '').trim()}</h4>;
      if (line.startsWith('- [ ]')) return (
        <div key={i} className="md-task">
          <div className="checkbox" />
          <span>{line.replace('- [ ]', '').trim()}</span>
        </div>
      );
      if (line.startsWith('- [')) {
        const match = line.match(/- \[(.*?)\]\((.*?)\)/);
        if (match) return (
          <a key={i} href={match[2]} target="_blank" rel="noreferrer" className="md-link">
            <lucide.ExternalLink size={14} /> {match[1]}
          </a>
        );
      }
      if (line.trim() === '') return <br key={i} />;
      return <p key={i} className="md-p">{line}</p>;
    });
  };

  return (
    <>
      <motion.div 
        className="panel-overlay"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        onClick={onClose}
      />
      <motion.div 
        className="drilldown-panel"
        initial={{ x: '100%' }}
        animate={{ x: 0 }}
        exit={{ x: '100%' }}
        transition={{ type: "spring", damping: 25, stiffness: 200 }}
      >
        <div className="panel-header">
          <div>
            <span className="panel-eyebrow">Micro-Plan</span>
            <h2 className="panel-title">{milestone.title}</h2>
          </div>
          <button className="icon-button" onClick={onClose}><lucide.X size={20} /></button>
        </div>

        <div className="panel-content">
          {loading ? (
            <div className="skeleton-container">
              <div className="skeleton-line w-1/2" />
              <div className="skeleton-box" />
              <div className="skeleton-box" />
              <div className="skeleton-box" />
              <div className="skeleton-line w-1/3 mt-8" />
              <div className="skeleton-box h-12" />
            </div>
          ) : error ? (
            <div className="error-state">
              <lucide.AlertCircle color="var(--error)" size={24} />
              <p>{error}</p>
            </div>
          ) : (
            <div className="markdown-content">
              {renderMarkdown(content)}
            </div>
          )}
        </div>

        <div className="panel-footer">
          <button className="nu-button-primary full-width">Save to Task Manager</button>
        </div>
      </motion.div>
    </>
  );
};

const TradeoffModal = ({ tradeoffState, onAccept, onRevert }) => {
  const [loading, setLoading] = useState(true);
  const [analysis, setAnalysis] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    let isMounted = true;
    const fetchTradeoff = async () => {
      try {
        const res = await api.compressTime(tradeoffState.milestone, tradeoffState.milestone.duration_weeks, tradeoffState.newDuration);
        if (isMounted) {
          setAnalysis(res);
          setLoading(false);
        }
      } catch (err) {
        if (isMounted) {
          setError("Failed to analyze tradeoff.");
          setLoading(false);
        }
      }
    };
    fetchTradeoff();
    return () => { isMounted = false; };
  }, [tradeoffState]);

  return (
    <>
      <motion.div className="modal-overlay" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} />
      <div className="modal-container-wrapper">
        <motion.div 
          className="tradeoff-modal"
          initial={{ opacity: 0, scale: 0.95, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95, y: 20 }}
        >
          <div className="modal-header warning">
            <lucide.AlertTriangle size={24} color="var(--warning)" />
            <h2>Aggressive Timeline Detected</h2>
          </div>

          <div className="modal-body">
            <p className="body-text">
              Compressing <strong>"{tradeoffState.milestone.title}"</strong> from {tradeoffState.milestone.duration_weeks} to {tradeoffState.newDuration} weeks requires a sacrifice.
            </p>

            <div className="analysis-box">
              {loading ? (
                <div className="skeleton-container">
                  <div className="skeleton-line" />
                  <div className="skeleton-line w-3/4" />
                </div>
              ) : error ? (
                <p className="error-text">{error}</p>
              ) : (
                <p className="tradeoff-message">{analysis.warning_message}</p>
              )}
            </div>
          </div>

          <div className="modal-footer">
            <button className="nu-button-ghost" onClick={onRevert}>Revert Timeline</button>
            <button 
              className="nu-button-primary warning-btn" 
              disabled={loading || error}
              onClick={() => onAccept(analysis?.affected_dependencies || [])}
            >
              Accept Trade-off
            </button>
          </div>
        </motion.div>
      </div>
    </>
  );
};

