import React, { useState, useEffect, useRef, useCallback, useLayoutEffect } from 'react';
import { motion, AnimatePresence, useMotionValue, animate } from 'framer-motion';
import { ArrowRight, AlertTriangle, GripVertical, X, AlertCircle, ExternalLink } from 'lucide-react';

const SEED_DREAM = "I want to build an AI tool for indie authors to format and market their books, getting to $1M ARR in 2 years. I know basic Python but no frontend, and I have $5k saved.";

const SEED_ROADMAP = {
  phases: [
    { id: "p1", title: "Foundation & Prototype", duration_weeks: 12, order: 1 },
    { id: "p2", title: "Beta & First Revenue", duration_weeks: 20, order: 2 },
    { id: "p3", title: "Scaling to $100k ARR", duration_weeks: 24, order: 3 }
  ],
  milestones: [
    { id: "m1", phase_id: "p1", title: "Learn Frontend Basics", description: "Complete Next.js & React fundamentals.", duration_weeks: 4, dependencies: [] },
    { id: "m2", phase_id: "p1", title: "Build Core Formatting Engine", description: "Python backend for text processing.", duration_weeks: 6, dependencies: [] },
    { id: "m3", phase_id: "p1", title: "Integrate Auth & DB", description: "Setup Supabase and connect to frontend.", duration_weeks: 2, dependencies: ["m1"] },
    { id: "m4", phase_id: "p2", title: "Launch Waitlist Page", description: "Collect emails from interested authors.", duration_weeks: 2, dependencies: ["m1"] },
    { id: "m5", phase_id: "p2", title: "Onboard 50 Beta Testers", description: "Manual onboarding and feedback collection.", duration_weeks: 8, dependencies: ["m2", "m3", "m4"] },
    { id: "m6", phase_id: "p3", title: "Implement Stripe Billing", description: "Self-serve subscription tiers.", duration_weeks: 4, dependencies: ["m5"] }
  ]
};

// --- UTILS & API ---

const parseJSONResponse = (text) => {
  try {
    const match = text.match(/```json\n([\s\S]*?)\n```/);
    if (match) return JSON.parse(match[1]);
    return JSON.parse(text);
  } catch (e) {
    console.error("Failed to parse AI JSON:", text);
    throw new Error("Invalid JSON response from AI");
  }
};

const api = {
  deconstructDream: async (dreamText, baseline) => {
    const prompt = `
      You are an expert product manager and systems thinker. Take this ambitious goal and break it down into a realistic, multi-year tech-tree of phases and milestones.
      Dream: "${dreamText}"
      Baseline Context: "${baseline}"

      Output ONLY valid JSON matching this structure:
      {
        "phases": [{ "id": "p1", "title": "Phase Name", "duration_weeks": 12, "order": 1 }],
        "milestones": [{ "id": "m1", "phase_id": "p1", "title": "Actionable Step", "description": "Details", "duration_weeks": 4, "dependencies": ["id_of_prereq_milestone"] }]
      }
      Ensure dependencies only reference valid milestone IDs that come BEFORE them logically.
    `;
    const res = await fetch('/api/ai/anthropic', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: "claude-opus-4-6",
        max_tokens: 2000,
        messages: [{ role: "user", content: prompt }]
      })
    });
    if (!res.ok) throw new Error("API Error");
    const data = await res.json();
    return parseJSONResponse(data.content[0].text);
  },

  drillDown: async (milestone, baseline) => {
    const prompt = `
      You are a tactical execution assistant. Break down this high-level milestone into exactly 3 immediate, highly specific tasks for this week, plus 2 exact learning resources.
      Milestone: "${milestone.title}"
      Description: "${milestone.description}"
      User Baseline: "${baseline}"

      Output ONLY Markdown format:
      ### Immediate Tasks
      - [ ] Task 1...
      - [ ] Task 2...
      - [ ] Task 3...

      ### Learning Resources
      - [Resource Name](Search Query or URL)
      - [Resource Name](Search Query or URL)
    `;
    const res = await fetch('/api/ai/openai', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
      body: JSON.stringify({
        model: "gpt-5.5",
        messages: [{ role: "user", content: prompt }],
        temperature: 0.3
      })
    });
    if (!res.ok) throw new Error("API Error");
    const data = await res.json();
    return data.choices[0].message.content;
  },

  compressTime: async (milestone, oldDuration, newDuration) => {
    const prompt = `
      You are a ruthless strategic constraint solver. The user is trying to compress a milestone's timeline.
      Milestone: "${milestone.title}"
      Original Duration: ${oldDuration} weeks
      New Duration: ${newDuration} weeks

      What specific trade-off must they make (e.g., spend money, cut scope, lower quality) to achieve this?
      Output ONLY valid JSON:
      {
        "warning_message": "To do this in X weeks, you must...",
        "affected_dependencies": [] // array of milestone IDs that might be at risk
      }
    `;
    const res = await fetch('/api/ai/gemini-compat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
      body: JSON.stringify({
        model: "gemini-3.1-pro-preview",
        messages: [{ role: "user", content: prompt }],
        temperature: 0.3
      })
    });
    if (!res.ok) throw new Error("API Error");
    const data = await res.json();
    return parseJSONResponse(data.choices[0].message.content);
  }
};

// --- COMPONENTS ---

const Header = () => (
  <header className="nu-header">
    <div className="nu-logo">Northeastern University</div>
    <div className="nu-product-name">Reverse-Engineer Dream</div>
  </header>
);

const DemoControls = ({ setScreen, setRoadmap }) => (
  <div className="demo-controls">
    <div className="demo-title">Demo Controls</div>
    <button onClick={() => setScreen('input')}>1. Input</button>
    <button onClick={() => setScreen('loading')}>2. Loading</button>
    <button onClick={() => { setRoadmap(SEED_ROADMAP); setScreen('roadmap'); }}>3. Roadmap (Seed)</button>
  </div>
);

const ScreenInput = ({ onSubmit }) => {
  const [dream, setDream] = useState("");
  const [baseline, setBaseline] = useState("");
  const [showBaseline, setShowBaseline] = useState(false);

  return (
    <motion.div 
      className="screen-container"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, scale: 0.95 }}
    >
      <div className="input-layout">
        <h1 className="display-text">What's the impossible goal?</h1>
        <p className="body-text tertiary" style={{ marginBottom: '32px' }}>
          Pour out your ambition. Don't worry about formatting or realism yet.
        </p>

        <motion.div layoutId="dream-origin" className="textarea-wrapper">
          <textarea 
            className="nu-textarea"
            placeholder="e.g., I want to build an AI tool for indie authors to format and market their books, getting to $1M ARR in 2 years..."
            value={dream}
            onChange={(e) => setDream(e.target.value)}
          />
        </motion.div>

        {showBaseline ? (
          <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} className="baseline-container">
            <label className="nu-label">My current baseline (skills, budget, time)</label>
            <input 
              type="text" 
              className="nu-input" 
              placeholder="e.g., I know basic Python, have $5k saved, can work 10hrs/week."
              value={baseline}
              onChange={(e) => setBaseline(e.target.value)}
            />
          </motion.div>
        ) : (
          <button className="nu-button-ghost" onClick={() => setShowBaseline(true)}>
            + Add Baseline Context
          </button>
        )}

        <div className="action-row">
          <button 
            className="nu-button-primary" 
            disabled={!dream.trim()}
            onClick={() => onSubmit(dream, baseline)}
          >
            Reverse-Engineer <ArrowRight size={16} style={{ marginLeft: '8px' }} />
          </button>
        </div>
      </div>
    </motion.div>
  );
};

const ScreenLoading = () => {
  const [textIdx, setTextIdx] = useState(0);
  const texts = [
    "Extracting prerequisites...",
    "Mapping skill dependencies...",
    "Estimating timelines...",
    "Structuring spatial roadmap..."
  ];

  useEffect(() => {
    const interval = setInterval(() => {
      setTextIdx(i => (i + 1) % texts.length);
    }, 2000);
    return () => clearInterval(interval);
  }, []);

  return (
    <motion.div 
      className="screen-container centered"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
    >
      <div className="loading-visual">
        <motion.div 
          layoutId="dream-origin"
          className="pulsing-node"
          animate={{ scale: [1, 1.2, 1], opacity: [0.5, 1, 0.5] }}
          transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
        />
        <motion.div 
          className="pulsing-ring"
          animate={{ scale: [1, 2], opacity: [0.8, 0] }}
          transition={{ duration: 2, repeat: Infinity, ease: "easeOut" }}
        />
      </div>
      <AnimatePresence mode="wait">
        <motion.p 
          key={textIdx}
          className="loading-text"
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -10 }}
        >
          {texts[textIdx]}
        </motion.p>
      </AnimatePresence>
    </motion.div>
  );
};

const MilestoneNode = ({ milestone, onDrilldown, onCompressRequest, isAtRisk, onHoverStart, onHoverEnd }) => {
  const x = useMotionValue(0);
  const [isDragging, setIsDragging] = useState(false);

  return (
    <motion.div 
      className={`milestone-node ${isAtRisk ? 'at-risk' : ''}`}
      data-node-id={milestone.id}
      drag="x"
      dragConstraints={{ left: -100, right: 0 }}
      dragElastic={0.1}
      style={{ x }}
      tabIndex={0}
      role="button"
      aria-label={`Milestone: ${milestone.title}, ${milestone.duration_weeks} weeks`}
      onDragStart={() => setIsDragging(true)}
      onDragEnd={(e, info) => {
        setIsDragging(false);
        if (info.offset.x < -50) {
          const newDuration = Math.max(1, Math.floor(milestone.duration_weeks / 2));
          onCompressRequest(milestone, newDuration, () => {
            animate(x, 0, { type: "spring", stiffness: 300, damping: 20 });
          });
        } else {
          animate(x, 0, { type: "spring", stiffness: 300, damping: 20 });
        }
      }}
      onClick={() => {
        if (!isDragging && x.get() === 0) onDrilldown(milestone);
      }}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onDrilldown(milestone);
        }
      }}
      onHoverStart={() => onHoverStart(milestone.id)}
      onHoverEnd={() => onHoverEnd(null)}
      whileHover={{ scale: 1.02, borderColor: 'var(--nu-red)' }}
      whileTap={{ scale: 0.98 }}
      layoutId={`node-${milestone.id}`}
    >
      <div className="node-header">
        <span className="node-duration">{milestone.duration_weeks}w</span>
        {isAtRisk && <AlertTriangle size={14} color="var(--warning)" />}
      </div>
      <h3 className="node-title">{milestone.title}</h3>
      <p className="node-desc">{milestone.description}</p>

      <div className="drag-handle">
        <GripVertical size={14} />
      </div>
    </motion.div>
  );
};

const ScreenRoadmap = ({ roadmap, onDrilldown, onCompressRequest, atRiskNodes }) => {
  const containerRef = useRef(null);
  const [lines, setLines] = useState([]);
  const [hoveredNode, setHoveredNode] = useState(null);

  const updateLines = useCallback(() => {
    if (!containerRef.current || !roadmap) return;
    const containerRect = containerRef.current.getBoundingClientRect();
    const newLines = [];

    roadmap.milestones.forEach(m => {
      if (!m.dependencies || m.dependencies.length === 0) return;
      const targetEl = document.querySelector(`[data-node-id="${m.id}"]`);
      if (!targetEl) return;
      const targetRect = targetEl.getBoundingClientRect();

      m.dependencies.forEach(depId => {
        const sourceEl = document.querySelector(`[data-node-id="${depId}"]`);
        if (!sourceEl) return;
        const sourceRect = sourceEl.getBoundingClientRect();

        const startX = sourceRect.right - containerRect.left;
        const startY = sourceRect.top + (sourceRect.height / 2) - containerRect.top;
        const endX = targetRect.left - containerRect.left;
        const endY = targetRect.top + (targetRect.height / 2) - containerRect.top;

        newLines.push({ id: `${depId}-${m.id}`, sourceId: depId, targetId: m.id, startX, startY, endX, endY });
      });
    });
    setLines(newLines);
  }, [roadmap]);

  useLayoutEffect(() => {
    const timer = setTimeout(updateLines, 100);
    window.addEventListener('resize', updateLines);
    return () => {
      clearTimeout(timer);
      window.removeEventListener('resize', updateLines);
    };
  }, [updateLines]);

  if (!roadmap) return null;

  const sortedPhases = [...roadmap.phases].sort((a, b) => a.order - b.order);

  return (
    <motion.div 
      className="roadmap-canvas"
      ref={containerRef}
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
    >
      {/* Accessibility: Hidden semantic list of the roadmap */}
      <div className="sr-only">
        <h2>Roadmap Milestones</h2>
        <ul>
          {roadmap.milestones.map(m => (
            <li key={m.id}>
              {m.title} - {m.duration_weeks} weeks. 
              {m.dependencies.length > 0 ? `Dependencies: ${m.dependencies.join(', ')}` : 'No dependencies.'}
            </li>
          ))}
        </ul>
      </div>

      <svg className="dependency-lines">
        {lines.map(line => {
          const cp1X = line.startX + (line.endX - line.startX) / 2;
          const cp1Y = line.startY;
          const cp2X = line.startX + (line.endX - line.startX) / 2;
          const cp2Y = line.endY;
          const pathD = `M ${line.startX} ${line.startY} C ${cp1X} ${cp1Y}, ${cp2X} ${cp2Y}, ${line.endX} ${line.endY}`;
          const isActive = hoveredNode === line.sourceId || hoveredNode === line.targetId;

          return (
            <path 
              key={line.id} 
              d={pathD} 
              className={`dep-path ${isActive ? 'active' : ''}`}
              initial={{ pathLength: 0, opacity: 0 }}
              animate={{ pathLength: 1, opacity: 1 }}
              transition={{ duration: 0.8, ease: "easeInOut" }}
            />
          );
        })}
      </svg>

      <div className="phases-container">
        {sortedPhases.map((phase, idx) => (
          <motion.div 
            key={phase.id} 
            className="phase-column"
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: idx * 0.2 }}
          >
            <div className="phase-header">
              <h2 className="phase-title">{phase.title}</h2>
              <span className="phase-duration">{phase.duration_weeks} weeks</span>
            </div>
            <div className="phase-milestones">
              {roadmap.milestones
                .filter(m => m.phase_id === phase.id)
                .map(m => (
                  <MilestoneNode 
                    key={m.id} 
                    milestone={m} 
                    onDrilldown={onDrilldown}
                    onCompressRequest={onCompressRequest}
                    isAtRisk={atRiskNodes.includes(m.id)}
                    onHoverStart={setHoveredNode}
                    onHoverEnd={setHoveredNode}
                  />
                ))}
            </div>
          </motion.div>
        ))}
      </div>
    </motion.div>
  );
};

const DrilldownPanel = ({ milestone, baseline, onClose }) => {
  const [content, setContent] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let isMounted = true;
    const fetchPlan = async () => {
      try {
        const md = await api.drillDown(milestone, baseline);
        if (isMounted) {
          setContent(md);
          setLoading(false);
        }
      } catch (err) {
        if (isMounted) {
          setError("Failed to generate micro-plan. Please try again.");
          setLoading(false);
        }
      }
    };
    fetchPlan();
    return () => { isMounted = false; };
  }, [milestone, baseline]);

  const renderMarkdown = (md) => {
    if (!md) return null;
    const lines = md.split('\n');
    return lines.map((line, i) => {
      if (line.startsWith('###')) return <h4 key={i} className="md-h4">{line.replace('###', '').trim()}</h4>;
      if (line.startsWith('- [ ]')) return (
        <div key={i} className="md-task">
          <div className="checkbox" />
          <span>{line.replace('- [ ]', '').trim()}</span>
        </div>
      );
      if (line.startsWith('- [')) {
        const match = line.match(/- \[(.*?)\]\((.*?)\)/);
        if (match) return (
          <a key={i} href={match[2]} target="_blank" rel="noreferrer" className="md-link">
            <ExternalLink size={14} /> {match[1]}
          </a>
        );
      }
      if (line.trim() === '') return <br key={i} />;
      return <p key={i} className="md-p">{line}</p>;
    });
  };

  return (
    <>
      <motion.div 
        className="panel-overlay"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        onClick={onClose}
      />
      <motion.div 
        className="drilldown-panel"
        initial={{ x: '100%' }}
        animate={{ x: 0 }}
        exit={{ x: '100%' }}
        transition={{ type: "spring", damping: 25, stiffness: 200 }}
      >
        <div className="panel-header">
          <div>
            <span className="panel-eyebrow">Micro-Plan</span>
            <h2 className="panel-title">{milestone.title}</h2>
          </div>
          <button className="icon-button" onClick={onClose} aria-label="Close panel"><X size={20} /></button>
        </div>

        <div className="panel-content">
          {loading ? (
            <div className="skeleton-container">
              <div className="skeleton-line w-1/2" />
              <div className="skeleton-box" />
              <div className="skeleton-box" />
              <div className="skeleton-box" />
              <div className="skeleton-line w-1/3 mt-8" />
              <div className="skeleton-box h-12" />
            </div>
          ) : error ? (
            <div className="error-state">
              <AlertCircle color="var(--error)" size={24} />
              <p>{error}</p>
            </div>
          ) : (
            <div className="markdown-content">
              {renderMarkdown(content)}
            </div>
          )}
        </div>

        <div className="panel-footer">
          <button className="nu-button-primary full-width">Save to Task Manager</button>
        </div>
      </motion.div>
    </>
  );
};

const TradeoffModal = ({ tradeoffState, onAccept, onRevert }) => {
  const [loading, setLoading] = useState(true);
  const [analysis, setAnalysis] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    let isMounted = true;
    const fetchTradeoff = async () => {
      try {
        const res = await api.compressTime(tradeoffState.milestone, tradeoffState.milestone.duration_weeks, tradeoffState.newDuration);
        if (isMounted) {
          setAnalysis(res);
          setLoading(false);
        }
      } catch (err) {
        if (isMounted) {
          setError("Failed to analyze tradeoff.");
          setLoading(false);
        }
      }
    };
    fetchTradeoff();
    return () => { isMounted = false; };
  }, [tradeoffState]);

  return (
    <>
      <motion.div className="modal-overlay" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} />
      <div className="modal-container-wrapper">
        <motion.div 
          className="tradeoff-modal"
          initial={{ opacity: 0, scale: 0.95, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95, y: 20 }}
          role="dialog"
          aria-modal="true"
        >
          <div className="modal-header warning">
            <AlertTriangle size={24} color="var(--warning)" />
            <h2>Aggressive Timeline Detected</h2>
          </div>

          <div className="modal-body">
            <p className="body-text">
              Compressing <strong>"{tradeoffState.milestone.title}"</strong> from {tradeoffState.milestone.duration_weeks} to {tradeoffState.newDuration} weeks requires a sacrifice.
            </p>

            <div className="analysis-box">
              {loading ? (
                <div className="skeleton-container">
                  <div className="skeleton-line" />
                  <div className="skeleton-line w-3/4" />
                </div>
              ) : error ? (
                <p className="error-text">{error}</p>
              ) : (
                <p className="tradeoff-message">{analysis.warning_message}</p>
              )}
            </div>
          </div>

          <div className="modal-footer">
            <button className="nu-button-ghost" onClick={onRevert}>Revert Timeline</button>
            <button 
              className="nu-button-primary warning-btn" 
              disabled={loading || error}
              onClick={() => onAccept(analysis?.affected_dependencies || [])}
            >
              Accept Trade-off
            </button>
          </div>
        </motion.div>
      </div>
    </>
  );
};

