    setRoadmap(prev => {
      const newRoadmap = { ...prev };
      const mIdx = newRoadmap.milestones.findIndex(m => m.id === tradeoffState.milestone.id);
      if (mIdx > -1) {
        newRoadmap.milestones[mIdx].duration_weeks = tradeoffState.newDuration;
      }
      return newRoadmap;
    });
    setAtRiskNodes(affectedDeps);
    setTradeoffState(null);
  };

  const handleRevertTradeoff = () => {
    if (tradeoffState.revertCallback) tradeoffState.revertCallback();
    setTradeoffState(null);
  };

  return (
    <div className="app-shell">
      <Header />
      <DemoControls setScreen={setScreen} setRoadmap={setRoadmap} />

      <main className="main-content">
        <AnimatePresence mode="wait">
          {screen === 'input' && (
            <ScreenInput key="input" onSubmit={handleDreamSubmit} />
          )}
          {screen === 'loading' && (
            <ScreenLoading key="loading" />
          )}
          {screen === 'roadmap' && (
            <ScreenRoadmap 
              key="roadmap" 
              roadmap={roadmap} 
              onDrilldown={setActiveMilestone}
              onCompressRequest={handleCompressRequest}
              atRiskNodes={atRiskNodes}
            />
          )}
        </AnimatePresence>
      </main>

      <AnimatePresence>
        {activeMilestone && (
          <DrilldownPanel 
            key="drilldown"
            milestone={activeMilestone} 
            baseline={dreamData.baseline}
            onClose={() => setActiveMilestone(null)} 
          />
        )}
        {tradeoffState && (
          <TradeoffModal 
            key="tradeoff"
            tradeoffState={tradeoffState}
            onAccept={handleAcceptTradeoff}
            onRevert={handleRevertTradeoff}
          />
        )}
      </AnimatePresence>
    </div>
  );
};

function __test_state_transitions__() {
  console.assert(typeof App === 'function', 'App must be a component');
  return true;
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}
